struct KLuaTimer { int nId; int nScriptIdx; char szFun[128]; int nParam; DWORD dwNextMs; }; static std::vector<KLuaTimer> s_LuaTimers; static int s_nNextTimerId=1;
int LuaAddTimer(Lua_State* L){ if (Lua_GetTopIndex(L)<3||!Lua_IsNumber(L,1)||!Lua_IsString(L,2)){Lua_PushNumber(L,0);return 1;} int nIdx=sFindScriptIdxByState(L); const char* szFun=Lua_ValueToString(L,2); if(nIdx<0||!szFun||!szFun[0]){Lua_PushNumber(L,0);return 1;} KLuaTimer t; t.nId=s_nNextTimerId++; t.nScriptIdx=nIdx; g_StrCpyLen(t.szFun,(char*)szFun,sizeof(t.szFun)); t.nParam=(int)Lua_ValueToNumber(L,3); double f=Lua_ValueToNumber(L,1); if(!(f>=1)) f=1; t.dwNextMs=GetTickCount()+(DWORD)(f*1000.0/18.0); s_LuaTimers.push_back(t); Lua_PushNumber(L,t.nId); return 1; }
int LuaDelTimer(Lua_State* L){ int nId=(int)Lua_ValueToNumber(L,1); for(i) if(s_LuaTimers[i].nId==nId){ s_LuaTimers.erase(..); Lua_PushNumber(L,1); return 1;} Lua_PushNumber(L,0); return 1; }
void KLuaTimer_Breathe(){ /* thu thap id den han TRUOC roi moi goi (callback co the AddTimer/DelTimer) */ for moi timer den han: KLuaScript* p=&g_ScriptSet[nScriptIdx]; if(!p->m_LuaState) {xoa; continue;} int nTop=0; p->SafeCallBegin(&nTop); Lua_State* S=p->m_LuaState; /* tach 'Obj:Fn' / 'Obj.Fn' */ char szObj[128], szM[128]; int nArgs=2; if(p=strchr(szFun,':')) { Lua_GetGlobal(S,szObj); lua_pushstring(S,szM); lua_gettable(S,-2); /* fn */ Lua_GetGlobal(S,szObj); /* self */ nArgs=3; } else if ('.') { Lua_GetGlobal(S,szObj); lua_pushstring(S,szM); lua_gettable(S,-2); lua_remove(S,-2);} else Lua_GetGlobal(S,szFun); Lua_PushNumber(S,nParam); Lua_PushNumber(S,nId); int nRet=Lua_Call(S,nArgs,2); double fNext = nRet==0 ? Lua_ValueToNumber(S,-2) : 0; if(nRet==0 && Lua_IsNumber(S,-1)) nParam=(int)Lua_ValueToNumber(S,-1); p->SafeCallEnd(nTop); if(fNext>=1) dwNextMs=GetTickCount()+(DWORD)(fNext*1000.0/18.0); else xoa; }
